 public float StructureScaleQ(SpaceTarget target,float incoming){var s=Organisations.Structures.FirstOrDefault(s=>"structure-q:"+s.Id==target.Id);if(s==null||incoming<=0)return 1;if(s.DamageWindowQ.AddSeconds(1)<=Now){s.DamageWindowQ=Now;s.DamageUsedQ=0;}float allowed=Math.Max(0,1000-s.DamageUsedQ);float amount=Math.Min(incoming,allowed);s.DamageUsedQ+=amount;s.RepairQ=Now.AddMinutes(15);return amount/incoming;}
