 public void SealStructureSafetyQ(StructureG s,bool destroyed){if(s.SafetySealedQ)return;s.SafetySealedQ=true;bool drops=destroyed&&(s.AbandonedLossQ||s.State=="Abandoned"||s.UnpoweredSince!=default&&s.UnpoweredSince.AddDays(7)<=Now||s.System.StartsWith("system:31")||int.TryParse(s.System.Replace("system:",""),out int sys)&&Galaxy42.ById.GetValueOrDefault(sys)?.RegionId==10000070||s.Kind is "Bridge" or "Skyhook");foreach(var owner in s.HoldsQ){var wrap=new SafetyWrapQ{Source=s.Id,Owner=owner.Key,System=s.System,Created=Now,State=drops?"Dropped":"Locked",Items=new(owner.Value.Items),Instances=owner.Value.Instances.ToList()};wrap.Value=wrap.Items.Sum(i=>ItemCatalog.Get(i.Key).Price*i.Value);SystemsQ.SafetyWraps.Add(wrap);if(drops){Commander.Wrecks.Add(new(){Id="wreck-d:q-safety:"+wrap.Id,System=s.System,Grid=s.GridQ,AbsoluteQ=s.AnchorQ,CellQ=s.CellQ,Position=(s.AnchorQ-SolarOrigin).Local,Expires=Now.AddDays(30),Items=new(wrap.Items),Instances=wrap.Instances.ToList()});wrap.Items.Clear();wrap.Instances.Clear();}owner.Value.Items.Clear();owner.Value.Instances.Clear();}LogQ("Physical structure custody sealed once / "+s.Id);BindWrecksD();}
 string SafetyDestinationQ(SafetyWrapQ w,bool local){if(!ImportedWorld43)return local?w.System:Systems.Where(s=>s.Security<.5&&s.Security>0).OrderBy(s=>JumpDistance(w.System,s.Id)).FirstOrDefault()?.Id??w.System;var origin=Galaxy42.ById[int.Parse(w.System[7..])];return Stations44.Stations.Where(s=>Galaxy42.ById.TryGetValue(int.Parse(s.System[7..]),out var system)&&(local?s.System==w.System:origin.Security>=.5?system.Security>=.5:system.Security>0&&system.Security<.5)).OrderBy(s=>BeaconDistance(w.System,s.System)).ThenBy(s=>s.Id).FirstOrDefault()?.Id??"";}
 public string RecoverSafetyQ(string id,bool local=true){var w=SystemsQ.SafetyWraps.FirstOrDefault(w=>w.Id==id&&w.State=="Locked");if(w==null||w.Owner!="player"&&!(w.Owner==Organisations.PlayerCorp&&HasRoleG("Director"))||Now<w.Created.AddDays(local?5:20)||!Docked)return "Owned mature safety wrap and destination docking required.";string dest=w.Destination.Length>0?w.Destination:SafetyDestinationQ(w,local);if(dest==""||StationKey44!=dest)return "Dock at the eligible safety destination.";decimal fee=Math.Round(w.Value*(LocationSystem(dest)==w.System?.005m:.15m),2);if(Balance<fee)return "Safety recovery wallet too small.";WalletChange(-fee,"Asset safety release");foreach(var i in w.Items)ChangeStack(i.Key,true,i.Value);foreach(var i in w.Instances)RestoreInstanceD(i,true,StationKey44);w.Fee=fee;w.Destination=dest;w.Items.Clear();w.Instances.Clear();w.State="Recovered";return "";}
 public void TickStructuresQ(double seconds){foreach(var s in Organisations.Structures.Where(s=>s.PhysicalQ)){var target=Targets.FirstOrDefault(t=>t.Id=="structure-q:"+s.Id);if(target!=null){s.ShieldQ=target.Shield;s.ArmorQ=target.Armor;s.HullQ=target.Hull;}if(s.State=="Reinforced"&&s.Due<=Now)s.State="Vulnerable";if(s.State is "Destroyed" or "Recovered"){SealStructureSafetyQ(s,s.State=="Destroyed");Targets.RemoveAll(t=>t.Id=="structure-q:"+s.Id);continue;}if(s.RepairQ!=default&&Now>=s.RepairQ&&s.State is "Online" or "Vulnerable"){s.ShieldQ=s.ArmorQ=s.HullQ=5000;if(target!=null)target.Shield=target.Armor=target.Hull=5000;s.RepairQ=default;}if(s.State=="Online"&&AccessQ(s,"player","Tether")&&!RobbingQ&&LawQ().Weapons<=Now&&LawQ().Criminal<=Now&&!Docked&&s.System==SystemId&&(SystemPosition-s.AnchorQ).Length<10000&&seconds>0){Player.Shield=Math.Min(Player.MaxShield,Player.Shield+(float)seconds*10);Player.Armor=Math.Min(Player.MaxArmor,Player.Armor+(float)seconds*10);Player.Hull=Math.Min(Player.MaxHull,Player.Hull+(float)seconds*10);}}
